insert into public.subjects (id, slug, name, short_name, description, icon, color, sort_order) values ('db324d9e-d1c1-4a19-a152-36a79b008ce0', 'networking', 'Networking', 'NET', 'Topologies, OSI & TCP/IP models, IP addressing, subnetting, protocols and ports.', 'network', '#0EA5E9', 1) on conflict (slug) do update set name = excluded.name, short_name = excluded.short_name, description = excluded.description, icon = excluded.icon, color = excluded.color, sort_order = excluded.sort_order;
