('a488ff3d-e4e5-43f2-a8ca-9eada6fcbe17', 'db324d9e-d1c1-4a19-a152-36a79b008ce0', 'Network Fundamentals', 'Devices, topologies, media and network types — the building blocks of every network.', 'quiz', 1, 60, null, 1, true),
('24a1782a-4415-45ba-a7a0-3aa03c6b060e', 'db324d9e-d1c1-4a19-a152-36a79b008ce0', 'OSI & TCP/IP Models', 'Simulate how data travels down the stack: arrange layers, encapsulation and the TCP handshake.', 'simulation', 2, 80, null, 2, true),
