('23ad4368-4a00-4bbc-a7d8-68b7cdd4d2d2', 'db324d9e-d1c1-4a19-a152-36a79b008ce0', 'Protocols & Ports Boss Challenge', 'Timed boss round. Know your ports and protocols cold — finish fast for a speed bonus!', 'challenge', 3, 120, 240, 4, true),
('aa70b913-16ac-4409-a39d-9237a51e1e6d', 'db324d9e-d1c1-4a19-a152-36a79b008ce0', 'Networking Pretest', 'Baseline assessment for Networking. Take it once before you start the quests. No feedback is shown so the results stay valid.', 'pretest', 2, 0, 900, 100, true),
('3250440d-20af-441f-a483-c01c80ee24e6', 'db324d9e-d1c1-4a19-a152-36a79b008ce0', 'Networking Posttest', 'Final assessment for Networking. Your instructor opens this at the end of the review period.', 'posttest', 2, 0, 900, 101, false),
