('6d22bee2-4eb5-464f-a2a0-72032dca7c52', 'bb499307-8d4e-4f9c-aab1-22f8b14476e6', 'SQL Query Lab', 'Work with a students table — write, complete and order SQL like you would in the lab.', 'simulation', 2, 90, null, 2, true),
